# application.yml: inserts and updates in batches
spring.jpa.properties.hibernate.jdbc.batch_size: 50
spring.jpa.properties.hibernate.order_inserts: true

// WRONG: batch_size is ignored for inserts
@Id @GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;

// RIGHT: ids come from a sequence, inserts can be batched
@Id @GeneratedValue(strategy = GenerationType.SEQUENCE)
private Long id;

@Service
public class ProductService {
    @Cacheable(value = "products", key = "#category", sync = true)   // prevents stampede
    public List<ProductResponse> list(String category) {
        return repository.findByCategory(category).stream().map(ProductResponse::from).toList();
    }
}

