@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 3)
@Measurement(iterations = 5)
@State(Scope.Benchmark)
public class ConcatBenchmark {
    List<String> words = Collections.nCopies(1000, "java");

    @Benchmark
    public String stringBuilder() {
        StringBuilder sb = new StringBuilder();
        for (String w : words) sb.append(w);
        return sb.toString();            // returned: the JIT cannot drop the work
    }

    @Benchmark
    public String join() {
        return String.join("", words);
    }
}

// WRONG: the result is discarded -> dead-code elimination
@Benchmark
public void join() {
    String.join("", words);
}

// RIGHT: return it, or blackhole.consume(...)
@Benchmark
public String join() {
    return String.join("", words);
}
